pub(crate) fn lt_item(mut nodes: &mut crate::port::Cells, mut attrs: &mut crate::port::Cells, mut text: &mut crate::port::Cells, parent: i32, marker: &[u8], body: &[u8], scheme: i32, value: i32, x: i32) -> i32 {
    // An `item` of the old Model under parent: its marker, text, scheme (`sub`), value (`aux`), text x (`fk-box`).
    let it: i32 = node_new(nodes, nk_item(), parent);
    let t0: i32 = crate::port::cells_len(text);
    text_append_utf8(text, body, 0, crate::port::blob_len(body));
    node_set_text(nodes, it, t0, crate::port::cells_len(text) - t0);
    let m0: i32 = crate::port::cells_len(text);
    text_append_utf8(text, marker, 0, crate::port::blob_len(marker));
    node_set_attr_text(nodes, attrs, it, fk_marker(), m0, crate::port::cells_len(text) - m0);
    node_set_sub(nodes, it, scheme);
    node_set_aux(nodes, it, value);
    node_set_attr_int(nodes, attrs, it, fk_box(), x);
    return it;
}
pub(crate) fn lt_rs(on: &mut crate::port::Cells, oa: &mut crate::port::Cells, orr: &mut crate::port::Cells, mut text: &mut crate::port::Cells, mut nodes: &mut crate::port::Cells, mut attrs: &mut crate::port::Cells, mut regions: &mut crate::port::Cells) -> i32 {
    // `rs-run` with its scratch made here; answers the new node count.
    let nm: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let stk: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let used: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let lay: &mut crate::port::Cells = &mut crate::port::Cells::new();
    return rs_run(on, oa, orr, text, nodes, attrs, regions, nm, stk, used, out, lay);
}
#[test]
fn test_items_become_lists_nested_by_the_x_of_their_text() {
    let on: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let oa: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let orr: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let nodes: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let attrs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let regions: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ledger: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let layout: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    model_init(on, oa, orr, text, pages, ledger, layout);
    let sec: i32 = node_new(on, nk_section(), 0);
    lt_item(on, oa, text, sec, &crate::testport::text_blob("1.")[..], &crate::testport::text_blob("one")[..], ls_sc_decimal(), 1, 9000);
    lt_item(on, oa, text, sec, &crate::testport::text_blob("2.")[..], &crate::testport::text_blob("two")[..], ls_sc_decimal(), 2, 9000);
    lt_item(on, oa, text, sec, &crate::testport::text_blob("a.")[..], &crate::testport::text_blob("inner a")[..], ls_sc_lower_alpha(), 1, 12000);
    lt_item(on, oa, text, sec, &crate::testport::text_blob("b.")[..], &crate::testport::text_blob("inner b")[..], ls_sc_lower_alpha(), 2, 12000);
    lt_item(on, oa, text, sec, &crate::testport::text_blob("3.")[..], &crate::testport::text_blob("three")[..], ls_sc_decimal(), 3, 9000);
    lt_item(on, oa, text, sec, &crate::testport::text_blob("5.")[..], &crate::testport::text_blob("five")[..], ls_sc_decimal(), 5, 9000);
    node_new(on, nk_paragraph(), sec);
    lt_item(on, oa, text, sec, &crate::testport::text_blob("1.")[..], &crate::testport::text_blob("again")[..], ls_sc_decimal(), 1, 9000);
    crate::testport::assert_eq(lt_rs(on, oa, orr, text, nodes, attrs, regions), 13, "seven items, two lists and a nested one, a paragraph");
    crate::testport::assert_eq(node_kind(nodes, 0), 1, "the document");
    crate::testport::assert_eq(node_kind(nodes, 2), nk_list(), "the first item opens a list under the section");
    crate::testport::assert_eq(node_parent(nodes, 2), 1, "in the section");
    crate::testport::assert_eq(node_sub(nodes, 2), 2, "an ordered one");
    crate::testport::assert_eq(node_kind(nodes, 3), nk_item(), "its first item");
    crate::testport::assert_eq(node_kind(nodes, 5), nk_list(), "the lettered items are a list of their own");
    crate::testport::assert_eq(node_parent(nodes, 5), 4, "inside the item before them");
    crate::testport::assert_eq(node_kind(nodes, 8), nk_item(), "then the third item continues the numbered list");
    crate::testport::assert_eq(node_parent(nodes, 8), 2, "in the outer list");
    crate::testport::assert_eq(node_attr_int_or(nodes, attrs, 9, fk_value(), -1), 5, "the item that skips gets an explicit value");
    crate::testport::assert_eq(node_attr_int_or(nodes, attrs, 8, fk_value(), -1), -1, "and the one that does not, none");
    crate::testport::assert_eq(node_kind(nodes, 10), nk_paragraph(), "a paragraph ends the list");
    crate::testport::assert_eq(node_kind(nodes, 11), nk_list(), "and a numbering that starts again is a new list");
    crate::testport::assert_eq(model_check(nodes, attrs, regions, text, pages, ledger, layout, st), 0, "the new Model is in document order");
}
#[test]
fn test_a_list_goes_on_across_a_page_milestone() {
    let on: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let oa: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let orr: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let nodes: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let attrs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let regions: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ledger: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let layout: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    model_init(on, oa, orr, text, pages, ledger, layout);
    page_new(pages, 1, 61200, 79200, 0, pk_vector());
    page_new(pages, 2, 61200, 79200, 0, pk_vector());
    lt_item(on, oa, text, 0, &crate::testport::text_blob("1.")[..], &crate::testport::text_blob("one")[..], ls_sc_decimal(), 1, 9000);
    lt_item(on, oa, text, 0, &crate::testport::text_blob("2.")[..], &crate::testport::text_blob("two")[..], ls_sc_decimal(), 2, 9000);
    let br: i32 = node_new(on, nk_break(), 0);
    node_set_sub(on, br, 2);
    lt_item(on, oa, text, 0, &crate::testport::text_blob("3.")[..], &crate::testport::text_blob("three")[..], ls_sc_decimal(), 3, 9000);
    crate::testport::assert_eq(lt_rs(on, oa, orr, text, nodes, attrs, regions), 6, "one list, three items, the milestone in the second");
    crate::testport::assert_eq(node_kind(nodes, 1), nk_list(), "a list");
    crate::testport::assert_eq(node_kind(nodes, 3), nk_item(), "an item");
    crate::testport::assert_eq(node_kind(nodes, 4), nk_break(), "the milestone is in it");
    crate::testport::assert_eq(node_parent(nodes, 4), 3, "kept in the item before it");
    crate::testport::assert_eq(node_parent(nodes, 5), 1, "and the next item is in the same list");
    crate::testport::assert_eq(model_check(nodes, attrs, regions, text, pages, ledger, layout, st), 0, "in document order");
}
#[test]
fn test_the_next_value_goes_on_the_list_whatever_its_first_line_indent() {
    let on: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let oa: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let orr: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let nodes: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let attrs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let regions: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ledger: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let layout: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    model_init(on, oa, orr, text, pages, ledger, layout);
    lt_item(on, oa, text, 0, &crate::testport::text_blob("(a)")[..], &crate::testport::text_blob("one")[..], ls_sc_lower_alpha(), 1, 9000);
    lt_item(on, oa, text, 0, &crate::testport::text_blob("(b)")[..], &crate::testport::text_blob("two")[..], ls_sc_lower_alpha(), 2, 9000);
    lt_item(on, oa, text, 0, &crate::testport::text_blob("(c)")[..], &crate::testport::text_blob("three, its first line indented")[..], ls_sc_lower_alpha(), 3, 11100);
    lt_item(on, oa, text, 0, &crate::testport::text_blob("(a)")[..], &crate::testport::text_blob("nested at last")[..], ls_sc_lower_alpha(), 1, 11100);
    crate::testport::assert_eq(lt_rs(on, oa, orr, text, nodes, attrs, regions), 7, "one list of three items, and the new `(a)` deep enough in is a list in the third");
    crate::testport::assert_eq(node_parent(nodes, 4), 1, "the indented `(c)` is in the list of `(a)` and `(b)`: its value is the next");
    crate::testport::assert_eq(node_kind(nodes, 5), nk_list(), "and a numbering that starts again, as far in, is a list inside it");
    crate::testport::assert_eq(node_parent(nodes, 5), 4, "in `(c)`");
    crate::testport::assert_eq(model_check(nodes, attrs, regions, text, pages, ledger, layout, st), 0, "in document order");
}
pub(crate) fn lt_caption(mut nodes: &mut crate::port::Cells, mut attrs: &mut crate::port::Cells, mut text: &mut crate::port::Cells, parent: i32, kind: i32) -> i32 {
    // A caption of the old Model (its kind in `aux`) with a label and a text.
    let c: i32 = node_new(nodes, nk_caption(), parent);
    let t0: i32 = crate::port::cells_len(text);
    let b: &[u8] = &crate::testport::text_blob("Table 1")[..];
    text_append_utf8(text, b, 0, crate::port::blob_len(b));
    node_set_attr_text(nodes, attrs, c, fk_label(), t0, crate::port::cells_len(text) - t0);
    node_set_aux(nodes, c, kind);
    return c;
}
#[test]
fn test_a_caption_is_bound_to_its_object() {
    let on: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let oa: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let orr: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let nodes: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let attrs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let regions: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ledger: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let layout: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    model_init(on, oa, orr, text, pages, ledger, layout);
    lt_caption(on, oa, text, 0, 2);
    node_new(on, nk_table(), 0);
    node_new(on, nk_paragraph(), 0);
    lt_caption(on, oa, text, 0, 1);
    crate::testport::assert_eq(lt_rs(on, oa, orr, text, nodes, attrs, regions), 6, "a table with its caption, a paragraph, a figure with its caption");
    crate::testport::assert_eq(node_kind(nodes, 1), nk_table(), "the table first");
    crate::testport::assert_eq(node_kind(nodes, 2), nk_caption(), "its caption is its first child");
    crate::testport::assert_eq(node_parent(nodes, 2), 1, "of it");
    crate::testport::assert_eq(node_attr_int_or(nodes, attrs, 2, fk_target(), -1), 1, "and points at it");
    crate::testport::assert_eq(node_kind(nodes, 3), nk_paragraph(), "the paragraph");
    crate::testport::assert_eq(node_kind(nodes, 4), nk_figure(), "a figure caption with no figure is wrapped in an empty figure");
    crate::testport::assert_eq(node_kind(nodes, 5), nk_caption(), "the caption is inside it");
    crate::testport::assert_eq(node_attr_int_or(nodes, attrs, 5, fk_target(), -1), 4, "pointing at it");
    crate::testport::assert_eq(model_check(nodes, attrs, regions, text, pages, ledger, layout, st), 0, "in document order");
}
#[test]
fn test_note_references_find_their_notes_and_bare_links_become_links() {
    let on: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let oa: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let orr: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let nodes: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let attrs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let regions: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ledger: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let layout: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    model_init(on, oa, orr, text, pages, ledger, layout);
    let p: i32 = node_new(on, nk_paragraph(), 0);
    let t1: i32 = node_new(on, nk_text(), p);
    let r: i32 = node_new(on, nk_ref(), p);
    let nt: i32 = node_new(on, nk_note(), 0);
    let np: i32 = node_new(on, nk_paragraph(), nt);
    let b: &[u8] = &crate::testport::text_blob("see www.example.com now")[..];
    let m: &[u8] = &crate::testport::text_blob("1")[..];
    let s0: i32 = crate::port::cells_len(text);
    text_append_utf8(text, b, 0, crate::port::blob_len(b));
    node_set_text(on, t1, s0, crate::port::cells_len(text) - s0);
    let m0: i32 = crate::port::cells_len(text);
    text_append_utf8(text, m, 0, crate::port::blob_len(m));
    node_set_attr_text(on, oa, r, fk_marker(), m0, 1);
    node_set_attr_text(on, oa, nt, fk_marker(), m0, 1);
    let s1: i32 = crate::port::cells_len(text);
    text_append_utf8(text, b, 0, crate::port::blob_len(b));
    node_set_text(on, np, s1, crate::port::cells_len(text) - s1);
    crate::testport::assert_eq(lt_rs(on, oa, orr, text, nodes, attrs, regions), 13, "the paragraph, the text split in three, the ref, the note");
    crate::testport::assert_eq(node_kind(nodes, 2), nk_text(), "the text before the link");
    crate::testport::assert_eq(node_kind(nodes, 3), nk_link(), "the link");
    crate::testport::assert_eq(node_first_child(nodes, 3), 4, "holding its text");
    crate::testport::assert_eq(node_kind(nodes, 5), nk_text(), "the text after it");
    crate::testport::assert_eq(node_kind(nodes, 6), nk_ref(), "the reference");
    crate::testport::assert_eq(node_attr_int_or(nodes, attrs, 6, fk_target(), -1), 7, "has the note as its target");
    crate::testport::assert_eq(node_kind(nodes, 7), nk_note(), "the note");
    crate::testport::assert_eq(node_kind(nodes, 10), nk_link(), "and the bare link in the note's own text is a link as well");
    crate::testport::assert_eq(model_check(nodes, attrs, regions, text, pages, ledger, layout, st), 0, "in document order");
}
